  "courseIntro": {
    "title": "សេចក្តីផ្តើមនៃមុខវិជ្ជា",
    "content": "## ១. ការពិពណ៌នាអំពីមុខវិជ្ជា\n\nមុខវិជ្ជា **គណិតវិទ្យាសម្រាប់កុំព្យូទ័រ (Mathematics for Computing)** គឺជាមុខវិជ្ជាគ្រឹះមួយដ៏សំខាន់បំផុត សម្រាប់និស្សិតដែលសិក្សាផ្នែកព័ត៌មានវិទ្យា និងបច្ចេកវិទ្យាព័ត៌មាន និងគមនាគមន៍ (ICT) នៅវិទ្យាស្ថានពហុបច្ចេកទេសភូមិភាគតេជោសែនសៀមរាប។\n\nចំណេះដឹងដូចជា **តក្កវិទ្យា**, **ទ្រឹស្តីសំណុំ**, **ពីជគណិតប៊ូលៀន**, **ប្រព័ន្ធរាប់** និង **វិធីសាស្ត្រសម្រាយបញ្ជាក់** គឺជាមូលដ្ឋានគ្រឹះដែលកុំព្យូទ័រប្រើប្រាស់ក្នុងការគណនា ការរក្សាទុកទិន្នន័យ ការរចនាសៀគ្វីឌីជីថល (Digital Logic Design) និងជាគ្រឹះនៃក្បួនដោះស្រាយ (Algorithms) ព្រមទាំងការសរសេរកម្មវិធីកម្រិតខ្ពស់។\n\n## ២. គោលបំណងនៃមុខវិជ្ជា\n\nក្រោយពីបានសិក្សាបញ្ចប់មុខវិជ្ជានេះ និស្សិតនឹងទទួលបានចំណេះដឹង និងសមត្ថភាពជាក់ស្តែងដូចខាងក្រោម៖\n- ចេះប្រើប្រាស់ឈ្នាប់តក្កវិទ្យា សង់តារាងភាពពិត និងវិភាគសុពលភាពនៃវិចារ\n- យល់ច្បាស់ពីប្រមាណវិធីលើសំណុំ និងការប្រើប្រាស់ដ្យាក្រាមវិនដោះស្រាយបញ្ហាជាក់ស្តែង\n- ចេះរចនា និងសម្រួលសៀគ្វីតក្កវិទ្យាដោយប្រើពីជគណិតប៊ូលៀន\n- ស្ទាត់ជំនាញក្នុងការបម្លែង និងគណនានព្វន្តលើប្រព័ន្ធរាប់ (គោលពីរ គោលប្រាំបី គោលដប់ និងគោលដប់ប្រាំមួយ)\n- យល់ពីរបៀបដែលកុំព្យូទ័ររក្សាទុកទិន្នន័យ (Sign-magnitude, 2's Complement, Floating Point និង BCD)\n- ចេះប្រើវិធីសាស្ត្រសម្រាយបញ្ជាក់បែបគណិតវិទ្យា និងវិចារកំណើនគណិតវិទ្យា (Mathematical Induction)\n\n## ៣. រចនាសម្ព័ន្ធមេរៀនទាំង ៦\n\nឯកសារនេះត្រូវបានចងក្រងជា ៦ មេរៀនធំៗ អមដោយលំហាត់អនុវត្ត និងអត្រាកំណែដំណោះស្រាយលម្អិត៖\n1. **មេរៀនទី១៖ តក្កវិទ្យា (Logic)**\n2. **មេរៀនទី២៖ ទ្រឹស្តីសំណុំ (Set Theory)**\n3. **មេរៀនទី៣៖ ពីជគណិតប៊ូលៀន (Boolean Algebra)**\n4. **មេរៀនទី៤៖ ប្រព័ន្ធរាប់ (Number Systems)**\n5. **មេរៀនទី៥៖ ការអនុវត្តប្រព័ន្ធរាប់ (Applications of Number Systems)**\n6. **មេរៀនទី៦៖ វិធីសាស្ត្រសម្រាយបញ្ជាក់ (Methods of Proof)**"
  },
