              "type": "paragraph",
              "text": "គេ​និយាយ​ថា​សំណុំ A ស្មើនឹង​សំណុំ B កាលណា​វា​មាន​ធាតុ​ដូចគ្នា​ដែលគេ​សរសេរ A = B។ គេ​អាច​និយាយ​ម្យ៉ាងទៀត​ថា សំណុំ​ពីរ A = B លុះត្រាតែ A ⊆ B និង B ⊆ A។"
