              "text": "៣.១ គេ​មាន​ចំនួន binary 8-bit ពីរ A = 10010101 និង B = 10101001។ បើ​គេ​បញ្ចូល​ទិន្នន័យ​នេះ​តាម​ច្រក​ទាំង​ប្រាំ (OR, AND, NOT, NOR, NAND) ចូរ​កំណត់​ធាតុ​ចេញ៖"
