              "text": "៣.៤ សង់​តារាង​ភាពពិត​នៃ​អនុ​គម​ន៍​ប៊ូលៀ​ននី​មួយៗ​ខាងក្រោម ហើយ​បន្ទាប់មក​ប្រៀបធៀប f1 និង f2៖"
