                "(⇐) ឧបមា​ថា A ⊂ B។ គ្រប់​ធាតុ​នៃ A ក៏​ជា​ធាតុ​នៃ B ដែរ ដូចនេះ​ធាតុ​រួម​នៃ A និង B គឺជា​ធាតុ​ទាំងអស់​នៃ A ពោល​គឺ A ∩ B = A។"
